from pathlib import Path
plan={}
def add(lab,lines):
 plan[lab]=[]
 for row in lines.strip().splitlines():
  title,path,action,ui=row.split('|',3)
  plan[lab].append(dict(title=title,path=path,action=action,ui=ui))
